package com.vetlink.emergencia.model;
import com.vetlink.mascota.model.Mascota; import com.vetlink.usuario.model.Usuario; import com.vetlink.veterinaria.model.Veterinaria; import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Table(name="emergencia") @Getter @Setter @NoArgsConstructor public class Emergencia { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Integer idEmergencia; @ManyToOne @JoinColumn(name="idMascota") private Mascota mascota; @ManyToOne @JoinColumn(name="idVeterinaria") private Veterinaria veterinaria; @ManyToOne @JoinColumn(name="idVeterinario") private Usuario veterinario; @Column(nullable=false) private String motivo; @Column(columnDefinition="TEXT") private String detalle; @Enumerated(EnumType.STRING) @Column(nullable=false) private EstadoEmergencia estado=EstadoEmergencia.PENDIENTE; @Column(nullable=false) private LocalDateTime creadaEn; }
